"""Build self-contained, offline ThaiHerb benchmark dashboard. No external JS/assets."""
from pathlib import Path
import json,csv,html
ROOT=Path(__file__).resolve().parents[1];R=ROOT/'results';O=ROOT/'dashboard'
O.mkdir(parents=True,exist_ok=True)
def rows(name):
 with open(R/name,encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
summary=rows('model_comparison_cluster_bootstrap.csv')
folds=rows('fold_eligibility_10.csv')
metrics=rows('per_fold_metrics.csv')
leak=rows('label_leakage_demonstration.csv')
case=rows('CASE_KEY_INTERNAL_45.csv')
manifest=json.loads((R/'benchmark_manifest.json').read_text())
null=json.loads((R/'null_permutation_summary.json').read_text())
expo={'summary':summary,'folds':folds,'metrics':metrics,'leak':leak,'case':case,'manifest':manifest,'null':null}
jsondata=json.dumps(expo,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
page='''<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ThaiHerb Paper 1 v0.7 | Validation</title>
<style>
:root{font-family:Inter,"Noto Sans Thai",system-ui,sans-serif;background:#f4f7f9;color:#16313f}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1240px;margin:auto;padding:25px}.hero{border-radius:19px;background:#123b4b;color:white;padding:35px}.eyebrow{font-size:12px;letter-spacing:.07em;color:#b8d8da;font-weight:bold}.hero h1{margin:13px 0;font-size:30px;line-height:1.24}.hero p{line-height:1.65;color:#deedf0;max-width:900px}.notice{background:#fff8e6;border-left:4px solid #bb821f;padding:14px 18px;margin:22px 0;border-radius:7px;line-height:1.6;font-size:14px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:20px 0}.metric,.panel{border:1px solid #d9e5eb;background:white;border-radius:12px;padding:20px}.metric strong{font-size:30px;display:block}.metric small{font-size:12px;color:#5b717c}nav{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}button,select,input{font-family:inherit;font-size:13px;padding:10px 13px;border-radius:8px;border:1px solid #aebfca;background:white;color:#173849}button{cursor:pointer}button.active{background:#174b5f;color:white;border-color:#174b5f}.tab{display:none}.tab.active{display:block}h2{font-size:20px;margin:0 0 15px}h3{font-size:16px}.muted{color:#657983;font-size:13px;line-height:1.6}.bar{height:12px;background:#e7eef2;border-radius:30px;overflow:hidden;flex:1}.fill{height:100%;background:#3684a5;border-radius:30px}.metricline{display:flex;align-items:center;gap:12px;margin:11px 0}.metricline .label{min-width:165px;font-size:13px}.metricline .value{width:50px;text-align:right;font-variant-numeric:tabular-nums;font-size:13px}.scroll{max-height:570px;overflow:auto;border:1px solid #e0e8ed;border-radius:9px}table{border-collapse:collapse;width:100%;font-size:12px}th,td{padding:10px;border-bottom:1px solid #e4edf0;text-align:left}th{position:sticky;top:0;background:#eaf1f5;white-space:nowrap}td{line-height:1.4}.tools{display:flex;gap:10px;flex-wrap:wrap;margin:10px 0 18px}.tools input,.tools select{min-width:180px;flex:1}.pill{border-radius:8px;background:#e4f2e9;color:#216347;padding:5px 8px;font-size:11px;font-weight:600}.bad{background:#fff0de;color:#92620d}.cardgrid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.mono{font-family:ui-monospace,monospace}.foot{margin:27px 0;font-size:12px;color:#607884}a{color:#126b8d;text-decoration:none}@media(max-width:700px){.wrap{padding:13px}.hero{padding:23px}.hero h1{font-size:24px}.metrics{grid-template-columns:repeat(2,1fr)}.metric strong{font-size:23px}.cardgrid{grid-template-columns:1fr}table{min-width:680px}.metricline .label{min-width:111px;font-size:11px}}
</style></head><body><main class="wrap"><header class="hero"><div class="eyebrow">THAIHERB RESEARCH / PAPER 1 / VALIDATION v0.7</div><h1>Held-Out Formula &amp; Expert Benchmark</h1><p>Internal out-of-sample evaluation across 10 Thai herbal formulas, candidate graph models, and a separately prepared, model-blinded 45-pair expert assessment. No independent expert scores have been collected.</p></header>
<div class="notice"><strong>Scientific boundary:</strong> Formula holdout predicts whether herbs co-occur in a withheld formula. This is <em>not</em> independent biomedical similarity, treatment efficacy, or expert gold validation. F02 is blocked from the 45-pair comparison because H07 is absent from the remaining Cooc training formulas. Chem/Core use a later 19-class candidate taxonomy, not recovered original vectors.</div>
<div class="metrics"><div class="metric"><strong>10</strong><small>Source-reviewed formulas</small></div><div class="metric"><strong>9 / 10</strong><small>Full-coverage holdout folds</small></div><div class="metric"><strong>45</strong><small>Distinct herb pairs</small></div><div class="metric"><strong>0</strong><small>Expert-adjudicated gold labels</small></div></div>
<nav><button class="active" data-tab="overview">Model comparison</button><button data-tab="folds">Formula holdouts</button><button data-tab="leakage">Leakage audit</button><button data-tab="expert">Expert assessment</button><button data-tab="limits">Scientific limitations</button></nav>
<section class="panel tab active" id="overview"><h2>Leave-One-Formula-Out performance</h2><p class="muted">Mean Average Precision (macro mean over 9 eligible held-out formulas). Larger is better for this narrow formula-cooccurrence ranking task. Fold-cluster bootstrap intervals are exploratory; n = 9.</p><div id="modelbars"></div><div class="scroll" style="margin-top:20px"><table><thead><tr><th>Model</th><th>Mean AP</th><th>AP 95% interval</th><th>Mean AUROC</th><th>Precision@5</th></tr></thead><tbody id="modeltable"></tbody></table></div><p class="muted">Chance prevalence averaged over eligible held-out formulas: 0.183. PairSupport ranks pair co-occurrence counts in the other nine formulas; it is not a graph embedding.</p></section>
<section class="panel tab" id="folds"><h2>Holdout eligibility and model performance</h2><div class="tools"><select id="chooseModel"></select><input id="foldSearch" placeholder="Filter by formula ID"></div><div class="scroll"><table><thead><tr><th>Held-out formula</th><th>Positive pairs</th><th>Coverage status</th><th>AP</th><th>AUROC</th><th>Precision@5</th></tr></thead><tbody id="foldtable"></tbody></table></div></section>
<section class="panel tab" id="leakage"><h2>Label leakage demonstration</h2><p class="muted">INVALID ORACLE below deliberately includes the held-out formula in its PairSupport count, exposing ground truth to the model. That model must not be used for claims.</p><div class="cardgrid"><div class="metric"><strong id="safeAP"></strong><small>Proper PairSupport Mean AP</small></div><div class="metric"><strong id="leakAP"></strong><small>INVALID oracle Mean AP</small></div></div><div class="scroll" style="margin-top:20px"><table><thead><tr><th>Held-out formula</th><th>Proper AP</th><th>Leaked AP (invalid)</th><th>Difference</th></tr></thead><tbody id="leaktable"></tbody></table></div><h3>Within-formula label permutation</h3><p id="permute" class="muted"></p></section>
<section class="panel tab" id="expert"><h2>45-pair expert evaluation pack</h2><p>Two independent reviewers should separately grade chemical similarity and formula-context similarity, using evidence not reused from training. Reviewer forms are deliberately free of model scores, rankings and held-out labels.</p><p><span class="pill bad">Not started</span> Expert 1: 0/45 &nbsp; Expert 2: 0/45 &nbsp; Adjudication: 0/45</p><div class="tools"><input id="pairSearch" placeholder="Find herb or case ID"></div><div class="scroll"><table><thead><tr><th>Case ID</th><th>Herb A</th><th>Herb B</th><th>Research status</th></tr></thead><tbody id="pairtable"></tbody></table></div><p class="muted">The blinded CSVs and independent review protocol are stored with the research package. This web dashboard displays case identities for project management but is not the reviewer blinding interface.</p></section>
<section class="panel tab" id="limits"><h2>Interpretation and open gates</h2><p><strong>Ground truth:</strong> Withheld formula co-occurrence only; not independent phytochemical, clinical, pharmacological or therapeutic similarity. Non-cooccurrence is not evidence of dissimilarity.</p><p><strong>Source overlap:</strong> All ten formula labels originate from the same official compendium. This is an internal record-level holdout, not an external source holdout. Herbs and formulas were selected ahead of this experiment.</p><p><strong>Cold start:</strong> F02 cannot be compared in the full 45-pair Cooc benchmark because H07 has zero occurrences among the remaining nine formulas.</p><p><strong>Chemistry:</strong> Chemistry channel includes later V3-derived assertions and a candidate 19-class mapping, not the unrecovered original Paper 1 chemical ontology.</p><p><strong>Uncertainty:</strong> Bootstrap uses formula clusters (only nine). Per-method comparisons are exploratory and not confirmatory claims. Multiple testing was not controlled.</p><p><strong>Expert evaluation:</strong> No human reviewer has provided ratings; all expert forms and gold labels remain blank. Ratings must be based on genuinely independent evidence, with adjudication and reviewer credential checks before interpretation as external validation.</p></section>
<footer class="foot">Data frozen for this exploratory analysis, 7 November 2026. Methodological context: Brière et al., Bioinformatics (2026), DOI 10.1093/bioinformatics/btag608. Dashboard is self-contained: no external scripts or services.</footer></main>
<script>window.RESEARCH_DATA=__PAYLOAD__;</script>
<script>
const d=window.RESEARCH_DATA;
const esc=x=>String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const num=(x,k=3)=>Number(x).toFixed(k);
function nav(){document.querySelectorAll('nav button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('nav button').forEach(n=>n.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.id===b.dataset.tab));}));}
function bars(){const rows=[...d.summary].sort((a,b)=>Number(b.mean_average_precision)-Number(a.mean_average_precision));document.querySelector('#modelbars').innerHTML=rows.map(r=>`<div class="metricline"><div class="label">${esc(r.method)}</div><div class="bar"><div class="fill" style="width:${100*Number(r.mean_average_precision)}%"></div></div><div class="value">${num(r.mean_average_precision)}</div></div>`).join('');document.querySelector('#modeltable').innerHTML=rows.map(r=>`<tr><td>${esc(r.method)}</td><td>${num(r.mean_average_precision)}</td><td>${num(r.ap_cluster_bootstrap_95ci_low)}–${num(r.ap_cluster_bootstrap_95ci_high)}</td><td>${num(r.mean_auroc)}</td><td>${num(r.mean_precision_at_5)}</td></tr>`).join('');}
function folds(){const el=document.querySelector('#chooseModel');el.innerHTML=d.summary.map(r=>`<option value="${esc(r.method)}">${esc(r.method)}</option>`).join('');el.value='PairSupport';el.addEventListener('change',foldtable);document.querySelector('#foldSearch').addEventListener('input',foldtable);foldtable();}
function foldtable(){const m=document.querySelector('#chooseModel').value,q=document.querySelector('#foldSearch').value.toLowerCase();document.querySelector('#foldtable').innerHTML=d.folds.filter(f=>f.heldout_formula_id.toLowerCase().includes(q)).map(f=>{let v=d.metrics.find(x=>x.heldout_formula_id===f.heldout_formula_id&&x.method===m),blocked=Number(f.full_45_pair_comparison_eligible)===0;return `<tr><td>${esc(f.heldout_formula_id)}</td><td>${esc(f.positive_pair_labels)}</td><td>${blocked?'<span class="pill bad">Blocked: cold-start</span>':'<span class="pill">Eligible</span>'}</td><td>${v?num(v.average_precision):'—'}</td><td>${v?num(v.auroc):'—'}</td><td>${v?num(v.precision_at_5):'—'}</td></tr>`}).join('');}
function leak(){document.querySelector('#safeAP').textContent=num(d.manifest.mean_proper_pair_AP);document.querySelector('#leakAP').textContent=num(d.manifest.observed_mean_oracle_AP);document.querySelector('#leaktable').innerHTML=d.leak.map(r=>`<tr><td>${esc(r.heldout_formula_id)}</td><td>${num(r.proper_pair_support_AP)}</td><td>${num(r.invalid_leaked_pair_support_AP)}</td><td>${num(r.leakage_delta_AP)}</td></tr>`).join('');document.querySelector('#permute').textContent=`Observed mean AP ${num(d.null.observed_pair_support_mean_AP)} vs permuted-label mean ${num(d.null.label_permuted_mean_AP_mean)}; exploratory one-sided permutation p = ${num(d.null.one_sided_permutation_p_exploratory,4)} (2,000 within-fold shuffles). This does not provide external biological validation.`;}
function pairtable(){let q=document.querySelector('#pairSearch').value.trim().toLowerCase();document.querySelector('#pairtable').innerHTML=d.case.filter(r=>Object.values(r).join(' ').toLowerCase().includes(q)).map(r=>`<tr><td class="mono">${esc(r.case_id)}</td><td>${esc(r.herb_a_th)} (${esc(r.herb_a_scientific)})</td><td>${esc(r.herb_b_th)} (${esc(r.herb_b_scientific)})</td><td><span class="pill bad">Unrated</span></td></tr>`).join('');}
nav();bars();folds();leak();document.querySelector('#pairSearch').addEventListener('input',pairtable);pairtable();
</script></body></html>'''
page=page.replace('__PAYLOAD__',jsondata)
path=O/'Paper1_Validation_v0.7.html'
path.write_text(page,encoding='utf-8')
print(path,len(page))